class CustomDimReduction:
    """Dual-scale SNE: mixture of a narrow-kernel local affinity graph and a
    wide-kernel global affinity graph, embedded with a Student-t kernel."""

    def __init__(self, n_components: int = 2, random_state: int | None = None):
        self.n_components = n_components
        self.random_state = random_state

    def _cond_p(self, D, perplexity):
        n = D.shape

n = X.shape[0]; d0 = X.shape[1]
if d0 > 50:
    X = PCA(50, random_state=self.random_state).fit_transform(X)
D = squareform(pdist(X, "sqeuclidean"))
if d0 <= 50:
    P = 0.9 * self._cond_p(D, 20.0) + 0.1 * self._cond_p(D, max(120.0, n / 25.0))
else:
    P = 0.6 * self._cond_p(D, 15.0) + 0.4 * self._cond_p(D, max(90.0, n / 25.0))
